{"content":"// cli_tool: MNIST MLP inference.
// Usage: ./cli_tool weights.json image.png
// Prints only the predicted digit (0-9) to stdout.
// Model: Linear(784->hidden) -> ReLU -> Linear(hidden->hidden) -> ReLU -> Linear(hidden->10), argmax.
// Input preprocessing: PNG decoded to RGBA, converted to grayscale with
// luminance weights, bilinearly resized to 28x28 if needed, scaled by 1/255.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

#include "cJSON.h"
#include "lodepng.h"

static char* read_entire_file(const char* path, size_t* out_len) {
    FILE* f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (n < 0) { fclose(f); return NULL; }
    char* buf = (char*)malloc((size_t)n + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t got = fread(buf, 1, (size_t)n, f);
    fclose(f);
    buf[got] = '\0';
    if (out_len) *out_len = got;
    return buf;
}

static bool load_vec(cJSON* obj, const char* key, std::vector<double>& out, int expect) {
    cJSON* arr = cJSON_GetObjectItemCaseSensitive(obj, key);
    if (!arr || !cJSON_IsArray(arr)) return false;
    int n = cJSON_GetArraySize(arr);
    if (expect >= 0 && n != expect) return false;
    out.resize(n);
    for (int i = 0; i < n; i++) {
        cJSON* v = cJSON_GetArrayItem(arr, i);
        if (!v || !cJSON_IsNumber(v)) return false;
        out[i] = v->valuedouble;
    }
    return true;
}

static bool load_mat(cJSON* obj, const char* key, std::vector<std::vector<double> >& out,
                     int rows, int cols) {
    cJSON* arr = cJSON_GetObjectItemCaseSensitive(obj, key);
    if (!arr || !cJSON_IsArray(arr)) return false;
    int n = cJSON_GetArraySize(arr);
    if (rows >= 0 && n != rows) return false;
    out.resize(n);
    for (int r = 0; r < n; r++) {
        cJSON* row = cJSON_GetArrayItem(arr, r);
        if (!row || !cJSON_IsArray(row)) return false;
        int m = cJSON_GetArraySize(row);
        if (cols >= 0 && m != cols) return false;
        out[r].resize(m);
        for (int c = 0; c < m; c++) {
            cJSON* v = cJSON_GetArrayItem(row, c);
            if (!v || !cJSON_IsNumber(v)) return false;
            out[r][c] = v->valuedouble;
        }
    }
    return true;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s weights.json image.png\n", argc > 0 ? argv[0] : "cli_tool");
        return 1;
    }
    const char* weights_path = argv[1];
    const char* image_path = argv[2];

    size_t json_len = 0;
    char* json_text = read_entire_file(weights_path, &json_len);
    if (!json_text) {
        fprintf(stderr, "Error: cannot read weights file '%s'\n", weights_path);
        return 1;
    }
    cJSON* root = cJSON_Parse(json_text);
    free(json_text);
    if (!root) {
        fprintf(stderr, "Error: invalid JSON in '%s'\n", weights_path);
        return 1;
    }

    int hidden_dim = 16;
    cJSON* hd = cJSON_GetObjectItemCaseSensitive(root, "hidden_dim");
    if (hd && cJSON_IsNumber(hd)) hidden_dim = (int)hd->valuedouble;

    std::vector<std::vector<double> > W1, Wh, Wo;
    std::vector<double> b1, bh, bo;
    bool ok = true;
    ok = ok && load_mat(root, "input_layer.weight", W1, hidden_dim, 784);
    ok = ok && load_vec(root, "input_layer.bias", b1, hidden_dim);
    ok = ok && load_mat(root, "hidden_layer.weight", Wh, hidden_dim, hidden_dim);
    ok = ok && load_vec(root, "hidden_layer.bias", bh, hidden_dim);
    ok = ok && load_mat(root, "output_layer.weight", Wo, 10, hidden_dim);
    ok = ok && load_vec(root, "output_layer.bias", bo, 10);
    cJSON_Delete(root);
    if (!ok) {
        fprintf(stderr, "Error: weights JSON missing expected arrays\n");
        return 1;
    }

    unsigned char* rgba = NULL;
    unsigned img_w = 0, img_h = 0;
    unsigned err = lodepng_decode32_file(&rgba, &img_w, &img_h, image_path);
    if (err) {
        fprintf(stderr, "Error: cannot decode PNG '%s': %s\n", image_path,
                lodepng_error_text(err));
        return 1;
    }

    // Grayscale in [0,1].
    std::vector<double> gray(img_w * img_h);
    for (unsigned i = 0; i < img_w * img_h; i++) {
        double r = rgba[4 * i + 0];
        double g = rgba[4 * i + 1];
        double b = rgba[4 * i + 2];
        gray[i] = (0.299 * r + 0.587 * g + 0.114 * b) / 255.0;
    }
    free(rgba);

    // Resize to 28x28 with bilinear interpolation if needed.
    const unsigned D = 28;
    std::vector<double> x(D * D);
    if (img_w == D && img_h == D) {
        x = gray;
    } else {
        for (unsigned y = 0; y < D; y++) {
            double sy = (img_h == 1) ? 0.0 : ((double)y * (img_h - 1)) / (D - 1);
            unsigned y0 = (unsigned)sy;
            unsigned y1 = y0 + 1 < img_h ? y0 + 1 : y0;
            double fy = sy - y0;
            for (unsigned xx = 0; xx < D; xx++) {
                double sx = (img_w == 1) ? 0.0 : ((double)xx * (img_w - 1)) / (D - 1);
                unsigned x0 = (unsigned)sx;
                unsigned x1 = x0 + 1 < img_w ? x0 + 1 : x0;
                double fx = sx - x0;
                double v00 = gray[y0 * img_w + x0];
                double v10 = gray[y0 * img_w + x1];
                double v01 = gray[y1 * img_w + x0];
                double v11 = gray[y1 * img_w + x1];
                x[y * D + xx] = (1 - fy) * ((1 - fx) * v00 + fx * v10) +
                                fy * ((1 - fx) * v01 + fx * v11);
            }
        }
    }

    // Forward pass.
    std::vector<double> h1(hidden_dim), h2(hidden_dim), logits(10);
    for (int i = 0; i < hidden_dim; i++) {
        double s = b1[i];
        for (int j = 0; j < 784; j++) s += W1[i][j] * x[j];
        h1[i] = s > 0 ? s : 0;
    }
    for (int i = 0; i < hidden_dim; i++) {
        double s = bh[i];
        for (int j = 0; j < hidden_dim; j++) s += Wh[i][j] * h1[j];
        h2[i] = s > 0 ? s : 0;
    }
    int best = 0;
    for (int i = 0; i < 10; i++) {
        double s = bo[i];
        for (int j = 0; j < hidden_dim; j++) s += Wo[i][j] * h2[j];
        logits[i] = s;
        if (i == 0 || s > logits[best]) best = i;
    }

    printf("%d\n", best);
    return 0;
}
